-- BSP CART catalog seed: products 9–100 (92 additions; total catalog target = 100).
-- Run this file in Supabase SQL Editor for the BSP-CART project.
-- It is safe to re-run: existing product IDs are left unchanged.
-- Expected products table columns match frontend/src/data/catalog.js mapping.

ON CONFLICT (id) DO NOTHING;

-- Keep generated IDs above the seeded range for future seller-added products.
SELECT setval(
  pg_get_serial_sequence('public.products', 'id'),
  GREATEST(COALESCE((SELECT MAX(id) FROM public.products), 1), 100),
  true
);
